def move_payouts_to_staff(apps, schema_editor):
    """Карточка сотрудника для каждого пользователя-сотрудника и для каждого, кому были выплаты."""
    User = apps.get_model('users', 'User')
    Staff = apps.get_model('users', 'Staff')
    EmployeePayout = apps.get_model('users', 'EmployeePayout')

    def staff_for(user):
        staff, _ = Staff.objects.get_or_create(user=user, defaults={
            'school_id': user.school_id, 'full_name': user.first_name or user.username, 'phone': user.phone_number,
            'external_id': user.external_id})
        return staff

    for user in User.objects.filter(role='EMPLOYEE'):
        staff_for(user)
    for payout in EmployeePayout.objects.select_related('employee'):
        payout.staff_tmp = staff_for(payout.employee)
        payout.save(update_fields=['staff_tmp'])


